\set ON_ERROR_STOP on
BEGIN;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception '%',label;end if;end$$;
create function pg_temp.denied(command text,label text) returns void language plpgsql as $$begin begin execute command;exception when raise_exception or insufficient_privilege or check_violation then return;end;raise exception 'Expected denial: %',label;end$$;
insert into auth.users(id,email,email_confirmed_at,raw_app_meta_data,aud,role) select ('cf000000-0000-4000-8000-00000000000'||n)::uuid,'billing-'||n||'@example.invalid',now(),'{"pms_admin_provisioned":true}','authenticated','authenticated' from generate_series(1,3)n;
insert into workspaces(id,name) values('cf000000-0000-4000-8000-000000000010','Billing fixture');
insert into workspace_members(workspace_id,user_id,role,display_name) select 'cf000000-0000-4000-8000-000000000010',('cf000000-0000-4000-8000-00000000000'||n)::uuid,case n when 1 then 'owner' when 2 then 'member' else 'client' end,'Person '||n from generate_series(1,3)n;
select set_config('request.jwt.claims','{"sub":"cf000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
insert into projects(id,workspace_id,name,client_name) values('cf000000-0000-4000-8000-000000000020','cf000000-0000-4000-8000-000000000010','Billing project','Billing client'),('cf000000-0000-4000-8000-000000000021','cf000000-0000-4000-8000-000000000010','Other project','Other client');
insert into project_members values('cf000000-0000-4000-8000-000000000010','cf000000-0000-4000-8000-000000000020','cf000000-0000-4000-8000-000000000003','guest');
insert into client_documents(id,workspace_id,project_id,client_id,kind,title,status,content,total_cents,created_by) values('cf000000-0000-4000-8000-000000000030','cf000000-0000-4000-8000-000000000010','cf000000-0000-4000-8000-000000000020','cf000000-0000-4000-8000-000000000003','Invoice','Monthly support','Draft','{"scope":"Support","items":[{"description":"Monthly service","quantity":1,"unit_cents":100000}],"tax_rate":0}',100000,'cf000000-0000-4000-8000-000000000001');
select pg_temp.denied($q$select create_billing_schedule('cf000000-0000-4000-8000-000000000030','monthly','America/New_York',current_date,null,14,false)$q$,'coverage confirmation required');
select create_billing_schedule('cf000000-0000-4000-8000-000000000030','monthly','America/New_York',make_date(extract(year from now())::integer+1,1,31),null,14,true);
-- Source edits do not change the recurring template.
update client_documents set total_cents=90000,content='{"scope":"Changed draft"}' where id='cf000000-0000-4000-8000-000000000030';
select run_billing_schedules((select starts_on+time '17:00' from billing_schedules where workspace_id='cf000000-0000-4000-8000-000000000010') at time zone 'UTC','cf000000-0000-4000-8000-000000000010');
select pg_temp.ok((select count(*)=1 from billing_occurrences where status='Draft'),'first cycle drafts once');
select pg_temp.ok((select d.status='Draft' and d.total_cents=100000 and d.deposit_cents=50000 and d.content->>'scope'='Support' and d.due_date=o.occurrence+14 from billing_occurrences o join client_documents d on d.id=o.document_id),'draft retains template and payment terms');
select pg_temp.ok(run_billing_schedules((select starts_on+time '17:00' from billing_schedules where workspace_id='cf000000-0000-4000-8000-000000000010') at time zone 'UTC','cf000000-0000-4000-8000-000000000010')=0,'repeat worker does not duplicate occurrence');
select pg_temp.ok((select next_on=(date_trunc('month',starts_on)+interval '2 months - 1 day')::date from billing_schedules),'month-end clamps to February');
select run_billing_schedules((select next_on+time '17:00' from billing_schedules where workspace_id='cf000000-0000-4000-8000-000000000010') at time zone 'UTC','cf000000-0000-4000-8000-000000000010');
select pg_temp.ok((select extract(day from next_on)=31 and extract(month from next_on)=3 from billing_schedules),'March restores day 31');
select set_billing_schedule_state((select id from billing_schedules),'Paused');
select pg_temp.ok(run_billing_schedules((select next_on+time '17:00' from billing_schedules) at time zone 'UTC','cf000000-0000-4000-8000-000000000010')=0,'paused schedule does not draft');
select set_billing_schedule_state((select id from billing_schedules),'Active');
select run_billing_schedules((select next_on+1+time '17:00' from billing_schedules) at time zone 'UTC','cf000000-0000-4000-8000-000000000010');
select pg_temp.ok((select count(*)=1 from billing_occurrences where status='Skipped'),'missed cycle recorded without backbilling');
select set_billing_schedule_state((select id from billing_schedules),'Cancelled');
select pg_temp.denied($q$select set_billing_schedule_state((select id from billing_schedules),'Active')$q$,'cancellation is final');
insert into client_documents(id,workspace_id,project_id,client_id,kind,title,status,content,total_cents,due_date,created_by) values('cf000000-0000-4000-8000-000000000031','cf000000-0000-4000-8000-000000000010','cf000000-0000-4000-8000-000000000020','cf000000-0000-4000-8000-000000000003','Invoice','Due invoice','Approved','{}',100000,current_date-10,'cf000000-0000-4000-8000-000000000001');
insert into email_preferences(workspace_id,user_id,enabled) values('cf000000-0000-4000-8000-000000000010','cf000000-0000-4000-8000-000000000003',true);
select save_billing_reminders('cf000000-0000-4000-8000-000000000031','UTC',3,7,3,true,false);
select run_billing_reminders((current_date+time '12:00') at time zone 'UTC','cf000000-0000-4000-8000-000000000010');
select pg_temp.ok((select count(*)=1 from billing_reminder_runs),'due reminder creates one in-app notice');
select pg_temp.ok(not exists(select 1 from studio_email_jobs where notification_id in(select notification_id from billing_reminder_runs)),'email is not enabled implicitly');
insert into client_payments(id,workspace_id,document_id,provider,provider_id,amount_cents) values('cf000000-0000-4000-8000-000000000050','cf000000-0000-4000-8000-000000000010','cf000000-0000-4000-8000-000000000031','Zelle','automation-paid',100000);
select pg_temp.ok(run_billing_reminders((current_date+7+time '12:00') at time zone 'UTC','cf000000-0000-4000-8000-000000000010')=0,'payment suppresses next reminder');
update client_payments set refunded_cents=5000 where id='cf000000-0000-4000-8000-000000000050';
select save_billing_reminders('cf000000-0000-4000-8000-000000000031','UTC',3,7,3,true,true);
select run_billing_reminders((current_date+7+time '12:00') at time zone 'UTC','cf000000-0000-4000-8000-000000000010');
select pg_temp.ok((select balance_cents=5000 from billing_reminder_runs order by reminder_on desc limit 1),'refund is reflected in current reminder balance');
select pg_temp.ok((select count(*)=1 from studio_email_jobs where notification_id in(select notification_id from billing_reminder_runs)),'email queues only after explicit enablement and recipient opt-in');
select pg_temp.ok(run_billing_reminders((current_date+7+time '12:00') at time zone 'UTC','cf000000-0000-4000-8000-000000000010')=0,'reminder occurrence is idempotent');
select disable_billing_reminders((select group_id from billing_reminder_rules));
select pg_temp.ok(not billing_reminder_ready((select group_id from billing_reminder_rules),'cf000000-0000-4000-8000-000000000003',true),'queued email becomes ineligible after opt-out');
select set_config('request.jwt.claims','{"sub":"cf000000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
set local role authenticated;
select pg_temp.ok((select count(*)=0 from billing_schedules),'clients cannot read internal recurring templates');
select pg_temp.denied($q$select process_workspace_billing('cf000000-0000-4000-8000-000000000010')$q$,'client cannot run billing');
select pg_temp.ok(not has_function_privilege('authenticated','run_billing_schedules(timestamptz,uuid)','execute') and not has_function_privilege('anon','save_billing_reminders(uuid,text,integer,integer,integer,boolean,boolean)','execute'),'billing worker privileges');
reset role;
select set_config('request.jwt.claims','{"sub":"cf000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select delete_workspace('cf000000-0000-4000-8000-000000000010','Billing fixture');
select pg_temp.ok(not exists(select 1 from billing_schedules where workspace_id='cf000000-0000-4000-8000-000000000010'),'explicit workspace deletion clears schedules and delivery history');
ROLLBACK;
